import copy,sys; sys.path.insert(0,'tools')
import belief_state as bsm; from pathlib import Path
cols=bsm.load_belief_ledgers(Path('.'))
r=lambda st,q: sorted(st['questions'][q]['hypotheses'],key=lambda h:-h['log_odds'])
for q in ('Q-001','Q-002','Q-003'):
    base=bsm.compute_belief_state(cols,root=Path('.')); L=r(base,q)[0]['hypothesis_id']
    for n in range(1,201):
        c=copy.deepcopy(cols)
        for i in range(n):
            e=f'EVL-PROBE-{i}'; c['evaluations'][e]={'evaluation_id':e,'target_hypothesis_id':L,
              'verdict':'narrows_scope','evidence_type':'fragment_thought_experiment',
              'session_id':f'P{i}','created_at':'2026-11-17T00:00:00Z','summary':'probe'}
        a=r(bsm.compute_belief_state(c,root=Path('.')),q)
        if a[0]['hypothesis_id']!=L: print(q,'N=',n,'->',a[0]['hypothesis_id']); break
    else: print(q,'N>200')
EOF
